package com.opensync.publisher.service;
import com.fasterxml.jackson.databind.ObjectMapper;import com.opensync.contracts.*;import com.opensync.persistence.entity.*;import com.opensync.persistence.repository.*;import java.util.UUID;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service
public class PublicationStateService{
 private final InventoryRepository inventory;private final InventorySyncJobRepository jobs;private final DeadLetterMessageRepository dlq;private final OutboxEventRepository outbox;private final ObjectMapper json;
 public PublicationStateService(InventoryRepository i,InventorySyncJobRepository j,DeadLetterMessageRepository d,OutboxEventRepository o,ObjectMapper json){inventory=i;jobs=j;dlq=d;outbox=o;this.json=json;}
 @Transactional public void complete(EventEnvelope<CanonicalInventory> event){inventory.findByPartnerIdAndPartnerListingId(event.partnerId(),event.payload().partnerListingId()).ifPresent(i->i.setSyncStatus(SyncStatus.PUBLISHED));jobs.findByRequestId(event.requestId()).ifPresent(j->j.transitionTo(SyncStatus.PUBLISHED));dlq.findById(event.eventId()).ifPresent(DeadLetterMessageEntity::resolve);try{var published=EventEnvelope.create("InventoryPublished",event.correlationId(),event.requestId(),event.partnerId(),event.payload());outbox.save(new OutboxEventEntity(published.eventId(),TopicNames.INVENTORY_PUBLISHED,event.partnerId()+":"+event.payload().partnerListingId(),json.writeValueAsString(published)));}catch(Exception e){throw new IllegalStateException("Unable to create inventory.published outbox event",e);}}
 @Transactional public void deadLetter(EventEnvelope<CanonicalInventory> event,String originalPayload,MarketplaceUnavailableException failure){var summary=failure.getClass().getSimpleName()+": "+failure.getMessage();dlq.save(new DeadLetterMessageEntity(event.eventId(),TopicNames.INVENTORY_UPDATED,originalPayload,ErrorCode.MAX_RETRIES_EXCEEDED.name(),"Marketplace unavailable after 4 attempts",summary,4));jobs.findByRequestId(event.requestId()).ifPresent(j->j.fail(SyncStatus.DEAD_LETTERED,ErrorCode.MAX_RETRIES_EXCEEDED.name(),failure.getMessage()));inventory.findByPartnerIdAndPartnerListingId(event.partnerId(),event.payload().partnerListingId()).ifPresent(i->i.setSyncStatus(SyncStatus.DEAD_LETTERED));outbox.save(new OutboxEventEntity(UUID.randomUUID(),TopicNames.INVENTORY_DEAD_LETTER,event.partnerId()+":"+event.payload().partnerListingId(),originalPayload));}
}
